-- Check if compatibility_metrics has same rows as transplant_matching when joined by donor+recipient
SELECT COUNT(*) FROM transplant_matching tm
JOIN compatibility_metrics cm ON cm.donor_ref_reg = tm.donor_ref_reg AND cm.recip_ref_reg = tm.recip_ref_reg;

-- Check how many matches in transplant_matching also exist in compatibility_metrics by match registry
SELECT COUNT(*) FROM transplant_matching tm
JOIN compatibility_metrics cm ON cm.match_comp_registry = tm.match_rec_registry;

-- Check how many rows have hla_mis_count = 0 and blood_compat like 'Compatible'
SELECT COUNT(*) FROM compatibility_metrics 
WHERE hla_mis_count = 0 AND UPPER(blood_compat) = 'COMPATIBLE';

-- Check how many rows have hla_mis_count = 0 and blood_compat like 'Incompatible'
SELECT COUNT(*) FROM compatibility_metrics 
WHERE hla_mis_count = 0 AND UPPER(blood_compat) = 'INCOMPATIBLE';

